import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import prisma from "../lib/prisma.js";
import jwt from "jsonwebtoken";

const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";

// Authorization 헤더에서 토큰 추출
function extractToken(request: FastifyRequest): string | null {
  const auth = request.headers.authorization;
  if (!auth) return null;
  const match = auth.match(/^Token\s+(.+)$/i);
  return match ? match[1] : null;
}

// 토큰 디코딩
function verifyToken(token: string): { id: string; username: string; email: string } {
  return jwt.verify(token, JWT_SECRET) as any;
}

// 슬러그 생성: 소문자, 공백→하이픈, 특수문자 제거
function slugify(title: string): string {
  return title
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s_]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

// 태그 정규화: 소문자, 공백 제거, 빈 값 필터링
function normalizeTags(tagList: (string | null | undefined)[]): string[] {
  if (!tagList) return [];
  const tags = tagList
    .map((t) => {
      if (t === null || t === undefined || t === "") return null;
      return t.trim().toLowerCase();
    })
    .filter((t): t is string => t !== null && t !== "");
  return [...new Set(tags)];
}

export async function articlesRoutes(app: FastifyInstance): Promise<void> {
  // POST /api/articles - 아티클 생성
  app.post("/api/articles", async (request, reply) => {
    const token = extractToken(request);
    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const { article } = (request.body as any) as { article?: any };
    const { title, description, body, tagList } = article || {};

    // 필수 필드 검증
    if (!title || title.trim() === "") {
      return reply.code(422).send({ errors: { title: ["can't be blank"] } });
    }
    if (!description || description.trim() === "") {
      return reply.code(422).send({ errors: { description: ["can't be blank"] } });
    }
    if (!body || body.trim() === "") {
      return reply.code(422).send({ errors: { body: ["can't be blank"] } });
    }

    const decoded = verifyToken(token);
    const normalizedTags = normalizeTags(tagList);

    // 태그 조회/생성 (트랜잭션)
    let tagRecords: { id: string; name: string }[] = [];
    if (normalizedTags.length > 0) {
      const existingTags = await prisma.tag.findMany({
        where: { name: { in: normalizedTags } },
        select: { id: true, name: true },
      });
      const existingNames = new Set((existingTags as Array<{ name: string }>).map((t) => t.name));
      const newTags = normalizedTags.filter((n) => !existingNames.has(n));

      if (newTags.length > 0) {
        const opts: any = { data: newTags.map((name) => ({ name })), skipDuplicates: true };
        await prisma.tag.createMany(opts);
      }
      tagRecords = await prisma.tag.findMany({
        where: { name: { in: normalizedTags } },
        select: { id: true, name: true },
      });
    }

    const slug = slugify(title);
    const created = await prisma.article.create({
      data: {
        title: title.trim(),
        description: description.trim(),
        body: body.trim(),
        slug,
        authorId: decoded.id,
        tags: {
          connect: tagRecords.map((t) => ({ id: t.id })),
        },
      },
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tags: { select: { name: true } },
      },
    });

    return reply.code(201).send({
      article: {
        title: created.title,
        slug: created.slug,
        description: created.description,
        body: created.body,
        tagList: (created.tags as Array<{ name: string }>).map((t) => t.name),
        createdAt: created.createdAt,
        updatedAt: created.updatedAt,
        favorited: false,
        favoritesCount: 0,
        author: {
          username: created.author.username,
          bio: created.author.bio ?? null,
          image: created.author.image ?? null,
        },
      },
    });
  });

  // GET /api/articles - 아티클 목록 조회 (필터: author, tag, favorited)
  app.get("/api/articles", async (request: any, reply) => {
    const token = extractToken(request);
    const authorFilter = request.query?.author as string | undefined;
    const tagFilter = request.query?.tag as string | undefined;
    const favoritedFilter = request.query?.favorited as string | undefined;
    const limit = Math.min(parseInt(request.query?.limit as string ?? "20", 10), 100);
    const offset = parseInt(request.query?.offset as string ?? "0", 10);

    // favorited 필터 — 먼저 존재하여 articleIds 확보
    let favArticleIds: string[] = [];
    if (favoritedFilter) {
      const favUser = await prisma.user.findUnique({ where: { username: favoritedFilter } });
      if (!favUser) {
        return reply.send({ articles: [], articlesCount: 0 });
      }
      favArticleIds = await prisma.$queryRaw<string[]>`
        SELECT article_id FROM "Favorite" WHERE user_id = ${favUser.id}
      `;
    }

    // author 필터
    let authorId: string | undefined;
    if (authorFilter) {
      const author = await prisma.user.findUnique({ where: { username: authorFilter } });
      if (!author) {
        return reply.send({ articles: [], articlesCount: 0 });
      }
      authorId = author.id;
    }

    // tag 필터
    let tagId: string | undefined;
    if (tagFilter) {
      const tag = await prisma.tag.findUnique({ where: { name: tagFilter } });
      if (!tag) {
        return reply.send({ articles: [], articlesCount: 0 });
      }
      tagId = tag.id;
    }

    // where 조건 구성
    const where: any = {};
    if (authorId) where.authorId = authorId;
    if (favArticleIds.length > 0) {
      where.id = { in: favArticleIds };
    }
    if (tagId) {
      where.tags = { some: { id: tagId } };
    }

    // 전체 카운트
    const total = await prisma.article.count({ where });

    const articles = await prisma.article.findMany({
      where,
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tags: { select: { name: true } },
      },
      orderBy: { createdAt: "desc" },
      take: limit,
      skip: offset,
    });

    // favorited 상태 확인 (토큰이 있는 경우)
    let currentUserId: string | null = null;
    if (token) {
      try {
        currentUserId = verifyToken(token).id;
      } catch {
        // invalid token, treat as no auth
      }
    }

    // favorited 상태 batch 체크
    const articleIds = articles.map((a: any) => a.id);
    let favoritedMap: Record<string, boolean> = {};
    let favCountMap: Record<string, number> = {};

    if (articleIds.length > 0) {
      const favResults = await prisma.$queryRaw<{ article_id: string; user_id: string }[]>`
        SELECT article_id, user_id FROM "Favorite" WHERE article_id IN (${articleIds})
      `;
      for (const row of favResults) {
        if (!favCountMap[row.article_id]) favCountMap[row.article_id] = 0;
        favCountMap[row.article_id]++;
        if (row.user_id === currentUserId) {
          favoritedMap[row.article_id] = true;
        }
      }
    }

    const result = articles.map((a: any) => ({
      title: a.title,
      slug: a.slug,
      description: a.description,
      tagList: (a.tags as Array<{ name: string }>).map((t) => t.name),
      createdAt: a.createdAt,
      updatedAt: a.updatedAt,
      favorited: favoritedMap[a.id] ?? false,
      favoritesCount: favCountMap[a.id] ?? 0,
      author: {
        username: a.author.username,
        bio: a.author.bio ?? null,
        image: a.author.image ?? null,
      },
    }));

    return reply.send({
      articles: result,
      articlesCount: total,
    });
  });

  // GET /api/articles/:slug - 단일 아티클 조회
  app.get("/api/articles/:slug", async (request: any, reply) => {
    const slug = request.params.slug as string;
    const token = extractToken(request);

    const article = await prisma.article.findUnique({
      where: { slug },
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tags: { select: { name: true } },
      },
    });

    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    // favorited 상태 확인
    let favorited = false;
    let favoritesCount = 0;
    let currentUserId: string | null = null;
    if (token) {
      try {
        currentUserId = verifyToken(token).id;
      } catch {
        // ignore
      }
    }

    const favResult = await prisma.$queryRaw<{ article_id: string; user_id: string }[]>`
      SELECT article_id, user_id FROM "Favorite" WHERE article_id = ${article.id}
    `;
    for (const row of favResult) {
      favoritesCount++;
      if (row.user_id === currentUserId) favorited = true;
    }

    return reply.send({
      article: {
        title: article.title,
        slug: article.slug,
        description: article.description,
        body: article.body,
        tagList: (article.tags as Array<{ name: string }>).map((t) => t.name),
        createdAt: article.createdAt,
        updatedAt: article.updatedAt,
        favorited,
        favoritesCount,
        author: {
          username: article.author.username,
          bio: article.author.bio ?? null,
          image: article.author.image ?? null,
        },
      },
    });
  });

  // PUT /api/articles/:slug - 아티클 수정
  app.put("/api/articles/:slug", async (request: any, reply) => {
    const slug = request.params.slug as string;
    const token = extractToken(request);
    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const article = await prisma.article.findUnique({
      where: { slug },
      include: { author: true, tags: true },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    const decoded = verifyToken(token);
    if (decoded.id !== article.authorId) {
      return reply.code(403).send({ errors: { article: ["not found"] } });
    }

    const { article: updateData } = (request.body as any) as { article?: any };
    const updates: any = {};
    const tagList = updateData?.tagList;

    if (updateData.title !== undefined) updates.title = updateData.title.trim();
    if (updateData.description !== undefined) updates.description = updateData.description.trim();
    if (updateData.body !== undefined) updates.body = updateData.body.trim();

    // tagList 처리: null이면 422, 배열이면 처리, 없으면 그대로
    if (tagList === null) {
      return reply.code(422).send({ errors: { tagList: ["can't be blank"] } });
    }
    if (tagList !== undefined) {
      const normalizedTags = normalizeTags(tagList);
      if (normalizedTags.length > 0) {
        const existingTags = await prisma.tag.findMany({
          where: { name: { in: normalizedTags } },
          select: { id: true, name: true },
        });
        const existingNames = new Set(existingTags.map((t) => t.name));
        const newTags = normalizedTags.filter((n) => !existingNames.has(n));
        if (newTags.length > 0) {
          const opts: any = { data: newTags.map((name) => ({ name })), skipDuplicates: true };
          await prisma.tag.createMany(opts);
        }
        const tagRecords = await prisma.tag.findMany({
          where: { name: { in: normalizedTags } },
          select: { id: true, name: true },
        });
        updates.tags = {
          set: tagRecords.map((t) => ({ id: t.id })),
        };
      } else {
        // 빈 배열이면 모든 태그 해제
        updates.tags = { set: [] };
      }
    }

    // slug 변경 가능성 체크 (현재 구현에서는 slug 유지)
    if (updates.title) {
      const newSlug = slugify(updates.title);
      updates.slug = newSlug;
    }

    const updated = await prisma.article.update({
      where: { slug },
      data: updates,
      include: {
        author: {
          select: { id: true, username: true, bio: true, image: true },
        },
        tags: { select: { name: true } },
      },
    });

    // favorited 상태 확인
    let favorited = false;
    let favoritesCount = 0;
    let currentUserId: string | null = null;
    if (token) {
      try {
        currentUserId = verifyToken(token).id;
      } catch {
        // ignore
      }
    }

    const favResult = await prisma.$queryRaw<{ article_id: string; user_id: string }[]>`
      SELECT article_id, user_id FROM "Favorite" WHERE article_id = ${updated.id}
    `;
    for (const row of favResult) {
      favoritesCount++;
      if (row.user_id === currentUserId) favorited = true;
    }

    return reply.send({
      article: {
        title: updated.title,
        slug: updated.slug,
        description: updated.description,
        body: updated.body,
        tagList: (updated.tags as Array<{ name: string }>).map((t) => t.name),
        createdAt: updated.createdAt,
        updatedAt: updated.updatedAt,
        favorited,
        favoritesCount,
        author: {
          username: updated.author.username,
          bio: updated.author.bio ?? null,
          image: updated.author.image ?? null,
        },
      },
    });
  });

  // DELETE /api/articles/:slug - 아티클 삭제
  app.delete("/api/articles/:slug", async (request: any, reply) => {
    const slug = request.params.slug as string;
    const token = extractToken(request);
    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const article = await prisma.article.findUnique({
      where: { slug },
      include: { author: true },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    const decoded = verifyToken(token);
    if (decoded.id !== article.authorId) {
      return reply.code(403).send({ errors: { article: ["not found"] } });
    }

    // 코멘트도 함께 삭제 (Cascade 설정됨)
    await prisma.article.delete({ where: { slug } });

    return reply.code(204).send();
  });
}

