// PUT /api/articles/:slug - 아티클 수정
app.put("/api/articles/:slug", async (request: any, reply) => {
  const slug = request.params.slug as string;
  const token = extractToken(request);
  if (!token) {
    return reply.code(401).send({ errors: { token: ["is missing"] } });
  }

  const article = await prisma.article.findUnique({
    where: { slug },
    include: { author: true, tags: true },
  });
  if (!article) {
    return reply.code(404).send({ errors: { article: ["not found"] } });
  }

  const decoded = verifyToken(token);
  if (decoded.id !== article.authorId) {
    return reply.code(403).send({ errors: { article: ["not found"] } });
  }

  const { article: updateData } = (request.body as any) as { article?: any };
  const updates: any = {};
  const tagList = updateData?.tagList;

  if (updateData.title !== undefined) updates.title = updateData.title.trim();
  if (updateData.description !== undefined) updates.description = updateData.description.trim();
  if (updateData.body !== undefined) updates.body = updateData.body.trim();

  // tagList 처리: null이면 422, 배열이면 처리, 없으면 그대로
  if (tagList === null) {
    return reply.code(422).send({ errors: { tagList: ["can't be blank"] } });
  }
  if (tagList !== undefined) {
    const normalizedTags = normalizeTags(tagList);
    if (normalizedTags.length > 0) {
      const existingTags = await prisma.tag.findMany({
        where: { name: { in: normalizedTags } },
        select: { id: true, name: true },
      });
      const existingNames = new Set(existingTags.map((t) => t.name));
      const newTags = normalizedTags.filter((n) => !existingNames.has(n));
      if (newTags.length > 0) {
        const opts: any = { data: newTags.map((name) => ({ name })), skipDuplicates: true };
        await prisma.tag.createMany(opts);
      }
      const tagRecords = await prisma.tag.findMany({
        where: { name: { in: normalizedTags } },
        select: { id: true, name: true },
      });
      updates.tags = {
        set: tagRecords.map((t) => ({ id: t.id })),
      };

