1	import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
2	import prisma from "../lib/prisma.js";
3	import jwt from "jsonwebtoken";
4	
5	const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
6	
7	// Authorization 헤더에서 토큰 추출
8	function extractToken(request: FastifyRequest): string | null {
9	  const auth = request.headers.authorization;
10	  if (!auth) return null;
11	  const match = auth.match(/^Token\s+(.+)$/i);
12	  return match ? match[1] : null;
13	}
14	
15	// 토큰 디코딩 (예외 처리 포함)
16	function verifyToken(token: string): { id: string; username: string; email: string } | null {
17	  try {
18	    return jwt.verify(token, JWT_SECRET) as any;
19	  } catch {
20	    return null;
21	  }
22	}
23	
24	// 슬러그 생성: 소문자, 공백→하이픈, 특수문자 제거
25	function slugify(title: string): string {
26	  return title
27	    .toLowerCase()
28	    .trim()
29	    .replace(/[^\w\s-]/g, "")
30	    .replace(/[\s_]+/g, "-")
31	    .replace(/^-+|-+$/g, "");
32	}
33	
34	// 태그 정규화: 소문자, 공백 제거, 빈 값 필터링
35	function normalizeTags(tagList: (string | null | undefined)[]): string[] {
36	  if (!tagList) return [];
37	  const tags = tagList
38	    .map((t) => {
39	      if (t === null || t === undefined || t === "") return null;
40	      return t.trim().toLowerCase();
41	    })
42	    .filter((t): t is string => t !== null && t !== "");
43	  return [...new Set(tags)];
44	}
45	
46	export async function articlesRoutes(app: FastifyInstance): Promise<void> {
47	  // POST /api/articles - 아티클 생성
48	  app.post("/api/articles", async (request, reply) => {
49	    const token = extractToken(request);
50	    if (!token) {
51	      return reply.code(401).send({ errors: { token: ["is missing"] } });
52	    }
53	
54	    const { article } = (request.body as any) as { article?: any };
55	    const { title, description, body, tagList } = article || {};
56	
57	    // 필수 필드 검증
58	    if (!title || title.trim() === "") {
59	      return reply.code(422).send({ errors: { title: ["can't be blank"] } });
60	    }
61	    if (!description || description.trim() === "") {
62	      return reply.code(422).send({ errors: { description: ["can't be blank"] } });
63	    }
64	    if (!body || body.trim() === "") {
65	      return reply.code(422).send({ errors: { body: ["can't be blank"] } });
66	    }
67	
68	    const decoded = verifyToken(token);
69	    if (!decoded) {
70	      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
71	    }
72	    const normalizedTags = normalizeTags(tagList);
73	
74	    // 태그 조회/생성 (트랜잭션)
75	    let tagRecords: { id: string; name: string }[] = [];
76	    if (normalizedTags.length > 0) {
77	      const existingTags = await prisma.tag.findMany({
78	        where: { name: { in: normalizedTags } },
79	        select: { id: true, name: true },
80	      });
81	      const existingNames = new Set((existingTags as Array<{ name: string }>).map((t) => t.name));
82	      const newTags = normalizedTags.filter((n) => !existingNames.has(n));
83	
84	      if (newTags.length > 0) {
85	        const opts: any = { data: newTags.map((name) => ({ name })), skipDuplicates: true };
86	        await prisma.tag.createMany(opts);
87	      }
88	      tagRecords = await prisma.tag.findMany({
89	        where: { name: { in: normalizedTags } },
90	        select: { id: true, name: true },
91	      });
92	    }
93	
94	    const slug = slugify(title);
95	    const created = await prisma.article.create({
96	      data: {
